<div class="page-head page-head--pages"><div><h1>Рубрики</h1><p>Рубрика превращает группу страниц в отдельный раздел сайта. Назовите её «Новости», «Блог», «Документы», «Проекты» или как нужно.</p></div></div>
<div class="dashboard-grid wp-categories-layout categories-layout--pages">
 <section class="panel"><h2>Добавить рубрику</h2><form method="post" action="<?=e(app_url('/studio/categories/save'))?>"><?=csrf_field()?><div class="field"><label>Название</label><input name="name" maxlength="150" required placeholder="Например: Новости"></div><div class="field"><label>Ярлык</label><input name="slug" maxlength="150" placeholder="novosti"></div><div class="field"><label>Описание</label><textarea name="description" rows="4" maxlength="2000" placeholder="Коротко опишите этот раздел"></textarea></div><button class="button primary">Добавить рубрику</button></form></section>
 <section><div class="cards-grid category-cards--pages"><?php foreach($categories as $category):?><article class="category-card"><div class="category-card__head"><div><h3><?=e($category['name'])?></h3><small>/category/<?=e($category['slug'])?></small></div><strong><?=(int)$category['entry_count']?></strong></div><p><?=e($category['description']??'Без описания')?></p><div class="category-card__actions"><a class="button small" target="_blank" rel="noopener" href="<?=e(app_url('/category/'.rawurlencode((string)$category['slug'])))?>">Открыть раздел</a><details><summary class="button small">Изменить</summary><form method="post" action="<?=e(app_url('/studio/categories/save'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$category['id']?>"><div class="field"><label>Название</label><input name="name" value="<?=e($category['name'])?>" required></div><div class="field"><label>Ярлык</label><input name="slug" value="<?=e($category['slug'])?>" required></div><div class="field"><label>Описание</label><textarea name="description" rows="3"><?=e($category['description']??'')?></textarea></div><button class="button primary small">Сохранить</button></form></details><form method="post" data-confirm="Удалить рубрику? Страницы сохранятся без неё." action="<?=e(app_url('/studio/categories/'.(int)$category['id'].'/delete'))?>"><?=csrf_field()?><button class="button small danger">Удалить</button></form></div></article><?php endforeach;?></div><?php if(!$categories):?><div class="empty-state"><h2>Рубрик пока нет</h2><p>Это нормально: страницы могут работать и без рубрик.</p></div><?php endif;?></section>
</div>
